/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountCartDrawer, type CartDrawerOptions } from "../../components/cart-drawer/CartDrawerEngine.js";
import type { MotionController } from "../../components/cart-drawer/motion-runtime";

export function CartDrawer({ options, className }: { options?: CartDrawerOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountCartDrawer(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="cart-drawer" />;
}

